SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(120) NOT NULL, username VARCHAR(120) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(60) NULL,
 password_hash VARCHAR(255) NOT NULL, role ENUM('member','writer','trusted_writer','editor','admin') NOT NULL DEFAULT 'member',
 status ENUM('pending','active','blocked') NOT NULL DEFAULT 'pending', login_banned_until DATETIME NULL, login_ban_reason VARCHAR(500) NULL, email_verified_at DATETIME NULL, activation_token_hash CHAR(64) NULL, activation_expires_at DATETIME NULL, password_reset_token_hash CHAR(64) NULL, password_reset_expires_at DATETIME NULL, two_factor_enabled TINYINT(1) NOT NULL DEFAULT 0, two_factor_secret VARCHAR(128) NULL, two_factor_recovery_codes TEXT NULL, bio TEXT NULL, avatar VARCHAR(255) NULL, writer_verified TINYINT(1) NOT NULL DEFAULT 0, writer_honored TINYINT(1) NOT NULL DEFAULT 0, writer_vip TINYINT(1) NOT NULL DEFAULT 0, writer_suspended_until DATETIME NULL, writer_suspension_reason VARCHAR(500) NULL, account_trashed_at DATETIME NULL, account_trashed_by BIGINT UNSIGNED NULL, account_trash_reason VARCHAR(500) NULL, account_trash_previous_status VARCHAR(20) NULL,
 last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(role), INDEX(status)
 ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS oauth_identities (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 provider VARCHAR(40) NOT NULL, subject VARCHAR(255) NOT NULL, user_id BIGINT UNSIGNED NOT NULL,
 email VARCHAR(190) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_oauth_provider_subject(provider,subject), UNIQUE KEY uq_oauth_provider_user(provider,user_id),
 INDEX idx_oauth_user(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS writer_profiles (
 user_id BIGINT UNSIGNED PRIMARY KEY, professional_title VARCHAR(190) NULL, cv_summary TEXT NULL, location VARCHAR(190) NULL, website VARCHAR(500) NULL, linkedin VARCHAR(500) NULL, portfolio_url VARCHAR(500) NULL, contact_email VARCHAR(190) NULL,
 experience_json LONGTEXT NULL, education_json LONGTEXT NULL, skills_json LONGTEXT NULL, certificates_json LONGTEXT NULL, languages_json LONGTEXT NULL, achievements_json LONGTEXT NULL, portfolio_json LONGTEXT NULL,
 is_public TINYINT(1) NOT NULL DEFAULT 0, show_contact TINYINT(1) NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT fk_writer_profile_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sort_order INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS category_translations (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL,
 name VARCHAR(160) NOT NULL, slug VARCHAR(190) NOT NULL, description TEXT NULL,
 UNIQUE(locale,slug), UNIQUE(category_id,locale), CONSTRAINT fk_ct_cat FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS articles (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, author_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NULL,
 status ENUM('draft','review','changes','published','archived') NOT NULL DEFAULT 'draft', is_featured TINYINT(1) NOT NULL DEFAULT 0,
 featured_image VARCHAR(255) NULL, legacy_path VARCHAR(255) NULL, views BIGINT UNSIGNED NOT NULL DEFAULT 0,
 published_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT fk_a_user FOREIGN KEY(author_id) REFERENCES users(id), CONSTRAINT fk_a_cat FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,
 INDEX(status,published_at), INDEX(author_id), INDEX(category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS article_translations (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, article_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL,
 title VARCHAR(255) NOT NULL, slug VARCHAR(220) NOT NULL, excerpt TEXT NULL, content LONGTEXT NOT NULL,
 seo_title VARCHAR(255) NULL, seo_description VARCHAR(320) NULL, seo_keywords VARCHAR(500) NULL, hashtags VARCHAR(500) NULL, og_image VARCHAR(255) NULL,
 status ENUM('draft','published') NOT NULL DEFAULT 'draft', review_state ENUM('draft','review','approved') NOT NULL DEFAULT 'draft', completeness_state ENUM('complete_ready','incomplete','needs_review','passed') NOT NULL DEFAULT 'complete_ready', completeness_source_hash CHAR(64) NULL, completeness_translation_hash CHAR(64) NULL, completeness_report LONGTEXT NULL, completeness_checked_at DATETIME NULL, completeness_checked_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE(locale,slug), UNIQUE(article_id,locale), FULLTEXT KEY ft_article(title,excerpt,content), CONSTRAINT fk_at_article FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS translation_validation_resolutions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, article_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL, issue_key CHAR(64) NOT NULL, reason VARCHAR(1000) NOT NULL, source_hash CHAR(64) NOT NULL, translation_hash CHAR(64) NOT NULL, resolved_by BIGINT UNSIGNED NOT NULL, resolved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_translation_resolution(article_id,locale,issue_key), INDEX(article_id,locale), FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(resolved_by) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(140) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS article_tags (article_id BIGINT UNSIGNED NOT NULL, tag_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(article_id,tag_id), FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS article_revisions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, article_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL,
 title VARCHAR(255) NULL, excerpt TEXT NULL, content LONGTEXT NULL, seo_title VARCHAR(255) NULL, seo_description VARCHAR(320) NULL, seo_keywords VARCHAR(500) NULL, hashtags VARCHAR(500) NULL, featured_image VARCHAR(500) NULL, category_id BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ads (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slot VARCHAR(80) NOT NULL, locale VARCHAR(20) NOT NULL DEFAULT '*', type ENUM('image','code') NOT NULL DEFAULT 'image', label VARCHAR(120) NULL,
 advertiser_name VARCHAR(190) NULL, price_note VARCHAR(190) NULL, admin_note TEXT NULL,
 image_url VARCHAR(500) NULL, target_url VARCHAR(500) NULL, code MEDIUMTEXT NULL, active TINYINT(1) NOT NULL DEFAULT 1, starts_at DATETIME NULL, ends_at DATETIME NULL, device VARCHAR(20) NOT NULL DEFAULT 'all', views BIGINT UNSIGNED NOT NULL DEFAULT 0, clicks BIGINT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 INDEX(slot,locale,active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(120) PRIMARY KEY, value MEDIUMTEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS redirects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_path VARCHAR(500) NOT NULL UNIQUE, target_url VARCHAR(500) NOT NULL, http_code SMALLINT NOT NULL DEFAULT 301) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS translation_strings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, namespace VARCHAR(80) NOT NULL, text_key VARCHAR(120) NOT NULL, locale VARCHAR(20) NOT NULL, value TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_translation_string(namespace,text_key,locale), INDEX(locale,namespace)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS not_found_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, path VARCHAR(700) NOT NULL, locale VARCHAR(20) NULL, referrer VARCHAR(700) NULL, hits BIGINT UNSIGNED NOT NULL DEFAULT 1, last_seen_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_404_path(path(255)), INDEX(last_seen_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, path VARCHAR(500) NOT NULL, mime VARCHAR(120) NOT NULL, alt_text VARCHAR(255) NULL, title VARCHAR(190) NULL, caption VARCHAR(500) NULL, description TEXT NULL, original_name VARCHAR(255) NULL, width INT UNSIGNED NULL, height INT UNSIGNED NULL, size_bytes BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS auth_throttles (
 throttle_key CHAR(64) PRIMARY KEY, attempts INT UNSIGNED NOT NULL DEFAULT 0, last_attempt_at DATETIME NOT NULL, locked_until DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pages (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, status ENUM('draft','published') NOT NULL DEFAULT 'draft', sort_order INT NOT NULL DEFAULT 0, template ENUM('standard','wide','landing') NOT NULL DEFAULT 'standard', deleted_at DATETIME NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS page_translations (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, page_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL, title VARCHAR(255) NOT NULL, slug VARCHAR(220) NOT NULL, content LONGTEXT NOT NULL, content_mode ENUM('visual','html') NOT NULL DEFAULT 'visual', custom_css LONGTEXT NULL, custom_js LONGTEXT NULL, featured_image VARCHAR(500) NULL,
 seo_title VARCHAR(255) NULL, seo_description VARCHAR(320) NULL, canonical_url VARCHAR(700) NULL, show_title TINYINT(1) NOT NULL DEFAULT 1, page_bg_color VARCHAR(20) NOT NULL DEFAULT '#ffffff', page_text_color VARCHAR(20) NOT NULL DEFAULT '#202522', content_width VARCHAR(20) NOT NULL DEFAULT 'standard', UNIQUE(locale,slug), UNIQUE(page_id,locale), FOREIGN KEY(page_id) REFERENCES pages(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS about_page_versions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,page_id BIGINT UNSIGNED NOT NULL,locale VARCHAR(20) NOT NULL,status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',content_json LONGTEXT NOT NULL,seo_title VARCHAR(255) NULL,seo_description VARCHAR(320) NULL,image_path VARCHAR(500) NULL,image_alt VARCHAR(255) NULL,created_by BIGINT UNSIGNED NULL,published_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,published_at DATETIME NULL,
 INDEX idx_about_page_locale_status(page_id,locale,status),INDEX idx_about_page_published(published_at),FOREIGN KEY(page_id) REFERENCES pages(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(published_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS writer_applications (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(60) NOT NULL,country VARCHAR(120) NULL,city VARCHAR(120) NULL,topics VARCHAR(500) NULL,experience TEXT NULL,sample_url VARCHAR(500) NULL,bio TEXT NOT NULL,status ENUM('new','reviewed','approved','rejected') NOT NULL DEFAULT 'new',admin_note TEXT NULL,verification_token_hash CHAR(64) NULL,verification_expires_at DATETIME NULL,email_verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status),INDEX(email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(80) NOT NULL DEFAULT 'info',title VARCHAR(190) NOT NULL,message TEXT NULL,link VARCHAR(500) NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,is_read,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,target_type VARCHAR(80) NULL,target_id BIGINT UNSIGNED NULL,details TEXT NULL,ip_address VARCHAR(64) NULL,user_agent VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),INDEX(action,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_v2_preferences (user_id BIGINT UNSIGNED PRIMARY KEY,theme VARCHAR(10) NOT NULL DEFAULT 'dark',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_v2_restriction_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,admin_id BIGINT UNSIGNED NOT NULL,action VARCHAR(60) NOT NULL,reason VARCHAR(500) NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NULL,previous_state LONGTEXT NULL,new_state LONGTEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),INDEX(action,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(admin_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,description VARCHAR(500) NULL,is_system TINYINT(1) NOT NULL DEFAULT 1,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(120) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,group_name VARCHAR(80) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(group_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_role_permissions (role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES admin_roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES admin_permissions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_user_roles (user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,assigned_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,role_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES admin_roles(id) ON DELETE CASCADE,FOREIGN KEY(assigned_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_user_permissions (user_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,effect ENUM('allow','deny') NOT NULL,assigned_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,permission_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES admin_permissions(id) ON DELETE CASCADE,FOREIGN KEY(assigned_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS admin_notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,assigned_to BIGINT UNSIGNED NULL,title VARCHAR(190) NOT NULL,body TEXT NULL,priority ENUM('normal','important','urgent') NOT NULL DEFAULT 'normal',status ENUM('new','doing','done') NOT NULL DEFAULT 'new',visibility ENUM('admin','management') NOT NULL DEFAULT 'admin',due_at DATETIME NULL,pinned TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(status,priority,due_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(assigned_to) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS writer_thanks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190) NULL,message TEXT NULL,locale VARCHAR(20) NOT NULL DEFAULT 'ar',award_type VARCHAR(40) NOT NULL DEFAULT 'featured',announce_on_site TINYINT(1) NOT NULL DEFAULT 0,starts_at DATETIME NULL,ends_at DATETIME NULL,notification_id BIGINT UNSIGNED NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,active),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS site_notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(190) NOT NULL,message TEXT NOT NULL,locale VARCHAR(20) NOT NULL DEFAULT '*',button_label VARCHAR(100) NULL,button_url VARCHAR(500) NULL,starts_at DATETIME NULL,ends_at DATETIME NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(active,locale,starts_at,ends_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS languages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,flag VARCHAR(32) NULL,dir ENUM('rtl','ltr') NOT NULL DEFAULT 'ltr',enabled TINYINT(1) NOT NULL DEFAULT 1,is_default TINYINT(1) NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(enabled,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO languages(code,name,flag,dir,enabled,is_default,sort_order) VALUES
('ar','ط§ظ„ط¹ط±ط¨ظٹط©','sy','rtl',1,1,0),
