CREATE TABLE IF NOT EXISTS story_submissions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(60) NULL,title VARCHAR(220) NOT NULL,story MEDIUMTEXT NOT NULL,image VARCHAR(500) NULL,
 locale VARCHAR(20) NOT NULL DEFAULT 'ar',status ENUM('new','reviewed','accepted','rejected') NOT NULL DEFAULT 'new',admin_note TEXT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(status,created_at),INDEX(email),INDEX(locale)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS contact_messages (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,subject VARCHAR(220) NULL,message TEXT NOT NULL,
 locale VARCHAR(20) NOT NULL DEFAULT 'ar',status ENUM('new','read','replied','archived') NOT NULL DEFAULT 'new',admin_note TEXT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(status,created_at),INDEX(email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS newsletter_subscribers (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,locale VARCHAR(20) NOT NULL DEFAULT 'ar',status ENUM('active','unsubscribed') NOT NULL DEFAULT 'active',source VARCHAR(80) NOT NULL DEFAULT 'footer',consented_at DATETIME NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(status,created_at),INDEX(locale)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS site_blocks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type ENUM('image','ad') NOT NULL DEFAULT 'image',slot VARCHAR(80) NOT NULL,locale VARCHAR(20) NOT NULL DEFAULT '*',title VARCHAR(190) NULL,image_url VARCHAR(500) NULL,target_url VARCHAR(500) NULL,ad_id BIGINT UNSIGNED NULL,sort_order INT NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(slot,locale,active,sort_order),FOREIGN KEY(ad_id) REFERENCES ads(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS story_of_night_selections (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, feature_date DATE NOT NULL, locale VARCHAR(20) NOT NULL DEFAULT 'ar', article_id BIGINT UNSIGNED NULL,
 selection_mode ENUM('automatic','manual') NOT NULL DEFAULT 'automatic', selected_by BIGINT UNSIGNED NULL, selected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uq_story_night_date_locale(feature_date,locale), INDEX(article_id,feature_date),
 FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE SET NULL, FOREIGN KEY(selected_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS story_of_night_exclusions (
 article_id BIGINT UNSIGNED PRIMARY KEY, excluded_by BIGINT UNSIGNED NULL, reason VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(excluded_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS story_of_night_overrides (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, article_id BIGINT UNSIGNED NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL,
 active TINYINT(1) NOT NULL DEFAULT 1, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(active,starts_at,ends_at),
 FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS integrations (
 service_key VARCHAR(80) PRIMARY KEY,
 enabled TINYINT(1) NOT NULL DEFAULT 0,
 config_json MEDIUMTEXT NULL,
 updated_by BIGINT UNSIGNED NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(enabled), INDEX(updated_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS custom_tracking_codes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(160) NOT NULL,
 location ENUM('head','body_start','body_end') NOT NULL DEFAULT 'body_end',
 consent_category ENUM('essential','analytics','marketing','ads') NOT NULL DEFAULT 'marketing',
 code MEDIUMTEXT NOT NULL,
 active TINYINT(1) NOT NULL DEFAULT 1,
 updated_by BIGINT UNSIGNED NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(active,location), INDEX(consent_category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Saradeeeb Community
CREATE TABLE IF NOT EXISTS community_categories (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sort_order INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(active,sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_category_translations (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, locale VARCHAR(20) NOT NULL,
 name VARCHAR(160) NOT NULL, slug VARCHAR(190) NOT NULL, description TEXT NULL,
 UNIQUE KEY uq_ccat_locale(category_id,locale), UNIQUE KEY uq_ccat_slug(locale,slug), INDEX(locale),
 FOREIGN KEY(category_id) REFERENCES community_categories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_topics (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, author_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NULL, locale VARCHAR(20) NOT NULL, article_id BIGINT UNSIGNED NULL,
 title VARCHAR(190) NOT NULL, slug VARCHAR(220) NOT NULL, excerpt VARCHAR(500) NULL, content MEDIUMTEXT NOT NULL, image VARCHAR(500) NULL, tags VARCHAR(500) NULL,
 status ENUM('open','closed','hidden') NOT NULL DEFAULT 'open', pinned TINYINT(1) NOT NULL DEFAULT 0, featured_week TINYINT(1) NOT NULL DEFAULT 0,
 views BIGINT UNSIGNED NOT NULL DEFAULT 0, replies_count INT UNSIGNED NOT NULL DEFAULT 0, likes_count INT UNSIGNED NOT NULL DEFAULT 0,
 last_activity_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uq_ctopic_slug(locale,slug), UNIQUE KEY uq_ctopic_article(article_id,locale), INDEX(locale,status,last_activity_at), INDEX(category_id,locale), INDEX(author_id,created_at), INDEX(featured_week,locale),
 FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES community_categories(id) ON DELETE SET NULL, FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_replies (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, topic_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, reply_to_reply_id BIGINT UNSIGNED NULL,
 content MEDIUMTEXT NOT NULL, status ENUM('visible','hidden','deleted') NOT NULL DEFAULT 'visible', likes_count INT UNSIGNED NOT NULL DEFAULT 0,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(topic_id,status,id), INDEX(user_id,created_at), INDEX(reply_to_reply_id),
 FOREIGN KEY(topic_id) REFERENCES community_topics(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(reply_to_reply_id) REFERENCES community_replies(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_likes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, target_type ENUM('topic','reply') NOT NULL, target_id BIGINT UNSIGNED NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_clike(user_id,target_type,target_id), INDEX(target_type,target_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_follows (
 user_id BIGINT UNSIGNED NOT NULL, topic_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(user_id,topic_id), INDEX(topic_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(topic_id) REFERENCES community_topics(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_saves (
 user_id BIGINT UNSIGNED NOT NULL, topic_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(user_id,topic_id), INDEX(topic_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(topic_id) REFERENCES community_topics(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_reports (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, target_type ENUM('topic','reply') NOT NULL, target_id BIGINT UNSIGNED NOT NULL,
 reason ENUM('abuse','spam','offtopic','copyright','other') NOT NULL DEFAULT 'other', details VARCHAR(1000) NULL,
 status ENUM('open','resolved','dismissed') NOT NULL DEFAULT 'open', reviewed_by BIGINT UNSIGNED NULL, reviewed_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 INDEX(status,created_at), INDEX(target_type,target_id), INDEX(user_id,target_type,target_id,status), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_bans (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL UNIQUE, reason VARCHAR(500) NULL, expires_at DATETIME NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 INDEX(expires_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_topic_activity (
 topic_id BIGINT UNSIGNED NOT NULL, activity_date DATE NOT NULL, views INT UNSIGNED NOT NULL DEFAULT 0, replies INT UNSIGNED NOT NULL DEFAULT 0, likes INT UNSIGNED NOT NULL DEFAULT 0,
 PRIMARY KEY(topic_id,activity_date), INDEX(activity_date), FOREIGN KEY(topic_id) REFERENCES community_topics(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS community_user_preferences (
 user_id BIGINT UNSIGNED PRIMARY KEY, email_replies TINYINT(1) NOT NULL DEFAULT 0, email_mentions TINYINT(1) NOT NULL DEFAULT 0, email_follows TINYINT(1) NOT NULL DEFAULT 0, email_admin TINYINT(1) NOT NULL DEFAULT 1,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Editorial messaging (v6)
CREATE TABLE IF NOT EXISTS editorial_threads (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, writer_id BIGINT UNSIGNED NOT NULL, article_id BIGINT UNSIGNED NULL,
 subject VARCHAR(190) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, status ENUM('open','archived') NOT NULL DEFAULT 'open',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(writer_id,status,updated_at), INDEX(article_id), FOREIGN KEY(writer_id) REFERENCES users(id) ON DELETE CASCADE,
 FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS editorial_messages (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, thread_id BIGINT UNSIGNED NOT NULL, sender_id BIGINT UNSIGNED NOT NULL,
 body TEXT NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 INDEX(thread_id,id), INDEX(sender_id), INDEX(read_at), FOREIGN KEY(thread_id) REFERENCES editorial_threads(id) ON DELETE CASCADE,
 FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS writer_username_redirects (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,old_username VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS editorial_message_attachments (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,message_id BIGINT UNSIGNED NOT NULL,path VARCHAR(500) NOT NULL,original_name VARCHAR(240) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(message_id),FOREIGN KEY(message_id) REFERENCES editorial_messages(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
